import json
S=json.load(open('sets.json')); M=json.load(open('media.json'))
ROBE=("ROBE = our Grinch robe of Images 3-5 (Image 3 front, Image 4 back, Image 5 the hood) reproduced one to one: red plush velvet upper part, green plush velvet lower part, thick white fluffy sherpa trims down the front and around the hem, fluffy lime-green fur cuffs, the Grinch face hood; lined red at the top and green at the bottom; never another robe.")
RF=["ccf9632e-bffd-46a1-9f7d-407a8a1bb79f","26930d56-68f4-445c-9d43-ebb4c1c7d438","dfb3995b-c326-4495-a226-bc212e60dabf"]
END=" Natural real movement with real weight, no morphing, ultra-realistic iPhone video, warm natural light. No captions, no emoji, no watermark; any overlay text of the input is removed. Silent."
def person(s): return f"PERSON = exactly the woman of Image 1 (same face, light skin, {s['hair']}), a different woman from the input, wearing {s['pj']}."
def P(k,vid,dur,extra_imgs,prompt):
    s=S[k]; med=[{"role":"video_references","value":vid},{"role":"image_references","value":s['girl']},{"role":"image_references","value":s['room']}]+[{"role":"image_references","value":x} for x in RF+extra_imgs]
    return {"model":"kling4_0","mode":"video-edit","duration":dur,"resolution":"1080p","aspect_ratio":"9:16","declined_preset_id":"24bae836-2c4a-48e0-89b6-49fcc0b21612","use_unlim":False,"medias":med,"prompt":prompt+END}
HEAD="Edit the input video. Copy it ONE TO ONE: same shots, camera, framing, movements and timing, second by second; same length as the input; keep the exact look of the input. "
def rC(k):
    s=S[k]; return P(k,M['rC'],7,[],HEAD+"TIMING: cuts at 3.46 s and 4.96 s. SHOT 1 (0-3.46 s, the room of Image 2): she stands barefoot holding the loosely rolled robe over her head with both hands; from 2.2 s she lowers it and it unrolls downward while BOTH HANDS KEEP HOLDING ITS TOP EDGE, the open robe hanging in front of her body. SHOT 2 (3.46-4.96 s): side view, she stands in an open white door wearing the robe, Grinch hood up, its long hem spread on the floor like a train. SHOT 3 (4.96-6.58 s): outside on the sunny driveway of the input, the same house, lawn, trees, black trash bin and small American flags; wearing the robe with the hood up she throws a trash bag in the bin, closes the lid and turns, the long robe trailing behind her. THE ROLL: rolled up LOOSELY and NOT tied - no belt, no ribbon, no bow around it, held closed only by her hands; the hood is rolled INSIDE the roll, nothing hangs from it. As it comes down it is already half unrolled, the plush layers loosening gradually; her hands never let go. The roll is BIG, THICK and FLUFFY, as thick as her head, red and green plush with white fluffy sherpa visible at both ends. Her head is uncovered in shot 1. Only ONE robe. HOOD MOTION: soft heavy plush hood, it flops down naturally with gravity and hangs still at the top under her hands; it never lifts, stands up, inflates or flips. NO BELT tied anywhere. CHANGE ONLY: "+person(s)+" ROOM = shots 1-2 in the living room of Image 2 exactly as it is, a small American flag on the wall; shot 3 keeps the outdoor place of the input. "+ROBE)
def g2(k):
    s=S[k]; return P(k,M['g2'],5,[],HEAD+"POV shot from her eyes looking down at her own legs and feet: she sits on the floor rug of the living room of Image 2 (the room fills the background exactly as in Image 2), legs stretched forward, wearing cozy white fluffy slippers; in front of her feet lies the robe ROLLED UP into a big thick fluffy roll, red plush with white sherpa and green fur ends, NOT tied, nothing around it. 0-3.9 s her feet rest still behind the roll; at 3.9-4.6 s she pushes the roll forward with her feet and it unrolls flat on the rug showing the open robe with its white sherpa lining, red top and green bottom, sleeves with lime-green fur cuffs and the Grinch hood. CHANGE ONLY: her pants are the pants of "+s['pj']+"; ROOM = the living room of Image 2; "+ROBE)
def g3(k):
    s=S[k]; return P(k,M['g3'],4,[],HEAD+"POV shot: she sits on the sofa of the living room of Image 2 (background exactly Image 2, Christmas tree, fireplace) and holds on her lap with both hands the robe ROLLED UP into a big thick roll, red plush with white sherpa and green fur ends, wrapped tightly in clear plastic film; 3.3-4.0 s she pulls the clear plastic off and it flies away, the bare fluffy roll stays in her hands, NOT tied, nothing around it. CHANGE ONLY: her sleeves are the sleeves of "+s['pj']+"; ROOM = the living room of Image 2; "+ROBE)
def g4(k):
    s=S[k]; return P(k,M['g4'],5,["35147aad-dbc4-4b7a-8fde-feb48f945b84"],HEAD+"She walks toward the camera down the Christmas aisle of a big home-decor store holding an iced coffee, sees something, gasps with an open mouth, covers her mouth, then points excitedly to the side at the display. LOGIC OF THE SCENE, exactly like the input: the shelves around her are full of Christmas decor; the display she points at is a tall stack of our red gift boxes of Image 6 with the HeatGrump Grinch robe. The store signs show no brand names. CHANGE ONLY: "+person(s).replace(f"wearing {s['pj']}","wearing a cozy oversized lime-green knit sweater dress with a big Grinch face and brown boots")+" "+ROBE.replace("ROBE = our Grinch robe","The robe in the boxes is our Grinch robe"))
def g5(k):
    s=S[k]; return P(k,M['g5'],4,[],HEAD+"In a bright clothing store, a man and a woman in black uniforms with red Santa hats pull a big clear plastic sheet off a large pyramid pile of folded robes on a long table and smile. Keep the two store workers, the store and the camera exactly as in the input. CHANGE ONLY THE PILE: every folded robe in the pile is our Grinch robe of Images 3-5 (red plush top, green plush bottom, white sherpa trims, Grinch face hood on top of each folded robe), neatly folded in rows; never pink robes. The woman of Image 1 and the room of Image 2 are not in this shot.")
def up(k):
    s=S[k]; return P(k,M['up'],5,[],HEAD+"Top-down shot on a dark green Christmas table with pine branches, fairy lights and cinnamon sticks: her hands turn a red square vacuum-sealed pouch printed with a big Grinch face and the words HEAT GRUMP, then cut it open with a purple box cutter. Keep the pouch, its print, the logo HEAT GRUMP and every movement exactly as in the input; the ONLY lettering in the video is HEAT GRUMP printed on our pouch. CHANGE ONLY: her forearms wear the sleeves of "+s['pj']+". The woman's face and the room are not in this shot.")
plan=[("G1-1",rC),("G1-2",g2),("G1-3",g4),("G2-1",g3),("G2-2",rC),("G2-3",up),("G3-1",g5),("G3-2",g2),("G3-3",g3)]
req=[{"index":i,"set":k,"hook":f.__name__,"params":f(k)} for i,(k,f) in enumerate(plan)]
json.dump(req,open('req1.json','w'),indent=1,ensure_ascii=False)
for r in req: print(r['index'],r['set'],r['hook'],r['params']['duration'],len(r['params']['prompt']))
